{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In a previous systematic review, Gomez-Ochoa et al revealed the lack of PPE, patient contact, and suboptimal hand hygiene as risk factors for COVID-19 among HCWs [12]. However, no meta-analysis was conducted. Furthermore, Chou et al, living rapid review focused on a broad range of coronavirus infections. Of the 64 studies that met inclusion criteria, 43 studies addressed the burden of HCW infections (15 on SARS-CoV2) and 34 studies addressed risk factors (3 on SARS-CoV-2). Only 3 studies included reported risk factors for SARS-CoV-2 infections among health workers.",
      "reason": "Explicitly summarizes existing evidence and gaps (limited prior studies and lack of meta-analysis), describing the current state of knowledge and uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "We present here the fi rst report of a living systematic review and meta-analysis to inform evidencebased guideline recommendations for effective preventive measures to reduce the occupational transmission of SARS-CoV-2 infection among HCWs.",
      "reason": "States the purpose and importance of the review (to inform guidelines and preventive measures) and emphasizes the urgent need due to the rapidly evolving pandemic."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "In a previous systematic review, Gomez-Ochoa et al revealed the lack of PPE, patient contact, and suboptimal hand hygiene as risk factors for COVID-19 among HCWs [12]. However, no meta-analysis was conducted. Furthermore, Chou et al, living rapid review focused on a broad range of coronavirus infections. Of the 64 studies that met inclusion criteria, 43 studies addressed the burden of HCW infections (15 on SARS-CoV2) and 34 studies addressed risk factors (3 on SARS-CoV-2). Only 3 studies included reported risk factors for SARS-CoV-2 infections among health workers.",
      "reason": "Identifies and cites prior similar reviews and explains their limitations (e.g., no meta-analysis, few SARS‑CoV‑2–specific risk-factor studies), justifying the need for the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses risk factors for infection rather than effects of an intervention; no mechanism of action of an intervention is relevant or described in the provided evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context and no logic model is presented or applicable based on the provided evidence."
    }
  ],
  "confidence": "85"
}

