{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Brie fl y, studies were eligible if they were (i) reporting PCR laboratory diagnosis of COVID-19 as an independent variable (ii) reporting one or more COVID-19 risk factors among HCWs with risk estimates (relative risk, odds ratio or hazard ratio) (iii) original, quantitative study design published in English or Mandarian.",
      "reason": "The manuscript specifies key question components and eligible study designs (original quantitative) and diagnostic requirement (PCR) but does not explicitly state eligible settings or any follow-up/timeframe requirements, so some required study-characteristic details are missing."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": \"Brie fl y, studies were eligible if they were ... published in English or Mandarian.\",
      "reason": "Language eligibility (English or Mandarin) is specified, but dissemination year and publication/report status (e.g., peer-reviewed, preprint) are not reported, so the report-characteristics eligibility statement is incomplete."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": \"Reasons for exclusion at full text review stage included lack of PCR con fi rmation of COVID-19 infection [24, 31 e 33, 36], and lack of evidence on risk estimates for COVID-19 risk factors [28].\",
      "reason": "The authors explicitly report exclusion reasons differentiating lack of outcome confirmation (no PCR) from lack of reported risk estimates, distinguishing outcomes not measured from outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": \"The summary measures calculated include a narrative report of all reported risk factors in the included studies, a pooled incidence of COVID-19 among health workers from included cohort studies and a pooled relative risk for risk factors reported by at least 2 included studies.\",
      "reason": "The manuscript specifies the groups used in syntheses (cohort studies for pooled incidence; risk factors reported by ≥2 studies for pooled RRs) and links these to the comparisons (e.g., PPE use, tracheal intubation, gender) presented in results/forest plots."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided for notable eligibility restrictions (for example, the language restriction to English/Mandarin or other limits); the text states criteria were developed iteratively but does not justify specific restrictions."
    }
  ],
  "confidence": 85
}

